package com.jarvis.ai;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.ImageFormat;import android.hardware.camera2.*;import android.media.*;import android.view.*;import java.nio.*;
public class CameraController{private CameraDevice cam;private ImageReader reader;private volatile byte[] last;public void open(Activity a,SurfaceView v){if(a.checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{Manifest.permission.CAMERA},42);return;}try{CameraManager m=(CameraManager)a.getSystemService(Context.CAMERA_SERVICE);String id=m.getCameraIdList()[0];reader=ImageReader.newInstance(1280,720,ImageFormat.JPEG,2);reader.setOnImageAvailableListener(r->{Image im=r.acquireLatestImage();if(im!=null)try{ByteBuffer b=im.getPlanes()[0].getBuffer();byte[] x=new byte[b.remaining()];b.get(x);last=x;}finally{im.close();}},null);m.openCamera(id,new CameraDevice.StateCallback(){public void onOpened(CameraDevice c){cam=c;try{Surface s=v.getHolder().getSurface();CaptureRequest.Builder b=c.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);b.addTarget(s);b.addTarget(reader.getSurface());c.createCaptureSession(java.util.Arrays.asList(s,reader.getSurface()),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession z){try{z.setRepeatingRequest(b.build(),null,null);}catch(Exception ignored){}}public void onConfigureFailed(CameraCaptureSession z){}},null);}catch(Exception ignored){}}public void onDisconnected(CameraDevice c){c.close();}public void onError(CameraDevice c,int e){c.close();}},null);}catch(Exception ignored){}}public byte[] latest(){return last;}public void close(){if(cam!=null){cam.close();cam=null;}if(reader!=null){reader.close();reader=null;}}}